const int TRIG = 9;
const int ECHO = 10;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
}

void loop() {
  digitalWrite(TRIG, HIGH);  // a 10 µs pulse starts a measurement
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  // echo time in µs ÷ 58 = distance in cm
  long cm = pulseIn(ECHO, HIGH, 30000) / 58;
  Serial.print(cm);
  Serial.println(" cm");
  delay(100);
}
